<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!events_schema_ready())redirect('upgrade-events.php');$u=user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$start=str_replace('T',' ',trim($_POST['starts_at']??''));$end=str_replace('T',' ',trim($_POST['ends_at']??''));if($title===''||$start===''||$end===''){flash('error','Title, start, and end are required.');}elseif(strtotime($end)<=strtotime($start)){flash('error','End time must be after start time.');}else{try{$s=db()->prepare("INSERT INTO events(owner_user_id,title,slug,subtitle,description,event_type,status,visibility,format,starts_at,ends_at,timezone,venue_name,virtual_url,capacity,registration_mode) VALUES(?,?,?,?,?,?,'pending',?,?,?,?,?,?,?,?,?)");$s->execute([$u['id'],$title,event_slug($title),trim($_POST['subtitle']??''),trim($_POST['description']??''),$_POST['event_type']??'panel',$_POST['visibility']??'public',$_POST['format']??'virtual',$start,$end,trim($_POST['timezone']??'America/New_York'),trim($_POST['venue_name']??''),trim($_POST['virtual_url']??''),(int)($_POST['capacity']??0)?:null,$_POST['registration_mode']??'open']);$id=(int)db()->lastInsertId();$banner=save_event_image('banner','banners',$id);if($banner)db()->prepare('UPDATE events SET banner_path=? WHERE id=?')->execute([$banner,$id]);flash('success','Event submitted for administrator approval.');redirect_route('events/manage.php',['id'=>$id]);}catch(Throwable $e){flash('error',$e->getMessage());}}}app_header('Create Event');?>
<section class="form-card"><p class="eyebrow">EVENT CREATOR</p><h1>Create an Event</h1><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><label class="full">Title<input name="title" required></label><label class="full">Subtitle<input name="subtitle" maxlength="255"></label><label>Event type<select name="event_type"><?php foreach(event_type_options() as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach?></select></label><label>Format<select name="format"><option value="virtual">Virtual</option><option value="physical">Physical</option><option value="hybrid">Hybrid</option></select></label><label>Starts<input type="datetime-local" name="starts_at" required></label><label>Ends<input type="datetime-local" name="ends_at" required></label><label>Time zone<input name="timezone" value="America/New_York"></label><label>Visibility<select name="visibility"><option value="public">Public</option><option value="members">Members only</option><option value="private">Private</option></select></label><label>Venue / room<input name="venue_name"></label><label>Virtual URL<input type="url" name="virtual_url"></label><label>Capacity<input type="number" min="1" name="capacity"></label><label>Registration<select name="registration_mode"><option value="open">Open RSVP</option><option value="approval">Approval required</option><option value="invite">Invite only</option><option value="closed">Closed</option></select></label><label class="full">Description<textarea name="description" rows="8"></textarea></label><label class="full">Banner image<input type="file" name="banner" accept="image/*"></label><div class="full"><button class="button primary">Create Event</button></div></form></section><?php app_footer();
